import React, { useState } from 'react';
import styled from 'styled-components';

const FormWrapper = styled.div`
  padding: 20px;
  max-width: 500px;
  margin: 0 auto;
  background-color: #f8f8f8;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h2`
  font-size: 24px;
  color: #333;
  text-align: center;
  margin-bottom: 20px;
`;

const InputWrapper = styled.div`
  margin-bottom: 15px;
`;

const Label = styled.label`
  display: block;
  font-size: 14px;
  color: #555;
  margin-bottom: 5px;
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
  margin-bottom: 5px;
  background-color: #fff;

  &:focus {
    outline: none;
    border-color: #4caf50;
  }
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: #fff;

  &:focus {
    outline: none;
    border-color: #4caf50;
  }
`;

const Button = styled.button`
  width: 100%;
  padding: 12px;
  font-size: 16px;
  background-color: #4caf50;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #45a049;
  }
`;

const EmployeeForm = () => {
  const [newEmployee, setNewEmployee] = useState({
    name: '',
    role: null, // Set default role to null
    phone: '',
    fixedSalary: '',
    daysWorked: '',
    expense: ''
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewEmployee((prevState) => ({
      ...prevState,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Submit the form logic
    console.log(newEmployee);
  };

  return (
    <FormWrapper>
      <Title>Add New Employee</Title>
      <form onSubmit={handleSubmit}>
        <InputWrapper>
          <Label htmlFor="name">Name</Label>
          <Input
            type="text"
            id="name"
            name="name"
            value={newEmployee.name}
            onChange={handleInputChange}
            required
            placeholder="Enter employee name"
          />
        </InputWrapper>

        <InputWrapper>
          <Label htmlFor="role">Role</Label>
          <Select
            id="role"
            name="role"
            value={newEmployee.role || ''}
            onChange={handleInputChange}
            required
          >
            <option value="" disabled>
              Select role
            </option>
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Lorry Manager</option>
            <option value="worker">Worker</option>
          </Select>
        </InputWrapper>

        <InputWrapper>
          <Label htmlFor="phone">Phone Number</Label>
          <Input
            type="text"
            id="phone"
            name="phone"
            value={newEmployee.phone}
            onChange={handleInputChange}
            required
            placeholder="Enter phone number"
          />
        </InputWrapper>

        <InputWrapper>
          <Label htmlFor="fixedSalary">Fixed Salary</Label>
          <Input
            type="number"
            id="fixedSalary"
            name="fixedSalary"
            value={newEmployee.fixedSalary}
            onChange={handleInputChange}
            required
            placeholder="Enter fixed salary"
          />
        </InputWrapper>

        <InputWrapper>
          <Label htmlFor="daysWorked">Days Worked</Label>
          <Input
            type="number"
            id="daysWorked"
            name="daysWorked"
            value={newEmployee.daysWorked}
            onChange={handleInputChange}
            required
            placeholder="Enter number of days worked"
          />
        </InputWrapper>

        <InputWrapper>
          <Label htmlFor="expense">Expense</Label>
          <Input
            type="number"
            id="expense"
            name="expense"
            value={newEmployee.expense}
            onChange={handleInputChange}
            required
            placeholder="Enter total expense"
          />
        </InputWrapper>

        <Button type="submit">Add Employee</Button>
      </form>
    </FormWrapper>
  );
};

export default EmployeeForm;
